/* esferas-modelo-data.js
   Modelo "Esferas del dragon / Dragon Balls" por Alien Byte (Sketchfab),
   licenca CC-BY-4.0 -- dar credito ao publicar/divulgar o projeto.

   O .glb (~1.09 MB) vai embutido em base64 aqui embaixo -- mesma ideia
   de drill-obj-data.js pra broca: sem fetch de rede nenhum, entao nao
   tem como dar 404 (foi exatamente isso que aconteceu com o caminho
   antigo, esferas_del_dragon_corrigido.glb, que nao existe mais nesse
   nome/lugar) nem quebrar em file://.

   Os NOMES aqui usam underscore ("1_Estrella_0") pra bater com o
   NOMES_ESFERAS que Nave/estacao_interior.html ja tem -- os nomes REAIS
   dentro do proprio glb usam espaco ("1 Estrella_0", sem underscore no
   primeiro numero), conferidos direto no JSON do arquivo; NOMES_REAIS_NO_GLB,
   mais abaixo, e' só o mapeamento interno pra achar cada grupo na cena
   carregada -- a API publica (NOMES) fica no formato que o resto do
   projeto ja espera, pra nao precisar mexer em mais nada.

   API exposta:
     window.NexusEsferasModelo = {
       NOMES: [ ...7 strings, mesma ordem 1..7 estrelas... ],
       carregar: function (callback) { ... }  // callback(erro, gruposArray)
     }
   gruposArray[i] e' um THREE.Group (clonavel) pra NOMES[i] -- na mesma
   ordem, index a index. Resultado fica em cache: chamar carregar() de
   novo (de outra pagina/instancia) nao reparseia o glb outra vez.
*/
(function (global) {
  "use strict";

  var NOMES = [
    "1_Estrella_0", "2_Estrellas_1", "3_Estrellas_2", "4_Estrellas_3",
    "5_Estrellas_4", "6_Estrellas_5", "7_Estrellas_6"
  ];

  // Nomes exatamente como estao dentro do glb (conferidos no JSON do
  // arquivo) -- usados so' aqui dentro pra localizar cada grupo depois
  // do parse; nao sao expostos pra fora.
  var NOMES_REAIS_NO_GLB = [
    "1 Estrella_0", "2 Estrellas_1", "3 Estrellas_2", "4 Estrellas_3",
    "5 Estrellas_4", "6 Estrellas_5", "7 Estrellas_6"
  ];

  var GLB_BASE64 =
    "";

  function base64ParaArrayBuffer(base64) {
    var binStr = atob(base64);
    var len = binStr.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) bytes[i] = binStr.charCodeAt(i);
    return bytes.buffer;
  }

  var cacheGrupos = null; // evita reparseiar o glb (~1MB) de novo em chamadas repetidas

  function carregar(callback) {
    if (cacheGrupos) { callback(null, cacheGrupos); return; }

    if (!window.THREE || !THREE.GLTFLoader) {
      callback(new Error(
        "NexusEsferasModelo: THREE.GLTFLoader nao encontrado -- carregue three.min.js e GLTFLoader.js antes deste script."
      ));
      return;
    }

    // Esse GLTFLoader.js e' de uma versao mais nova do three.js que
    // espera THREE.ColorManagement (adicionado bem depois da versao de
    // three.min.js usada no resto do projeto) -- sem isso,
    // addPrimitiveAttributes() quebra tentando ler
    // ColorManagement.workingColorSpace mesmo em malhas sem cor de
    // vertice (o "&&" nao livra a primeira metade de rodar). Confirmado
    // por log de console real: "TypeError: can't access property
    // workingColorSpace, three.ColorManagement is undefined". Shim
    // minimo, sem editar o arquivo de terceiros.
    if (!THREE.ColorManagement) {
      THREE.ColorManagement = { workingColorSpace: THREE.LinearSRGBColorSpace };
    }

    var buffer;
    try {
      buffer = base64ParaArrayBuffer(GLB_BASE64);
    } catch (erroDecode) {
      callback(erroDecode);
      return;
    }

    new THREE.GLTFLoader().parse(buffer, "", function (gltf) {
      var porNomeReal = {};
      gltf.scene.traverse(function (o) {
        if (o.name) porNomeReal[o.name] = o;
      });

      var faltando = [];
      var grupos = NOMES_REAIS_NO_GLB.map(function (nomeReal, i) {
        var achado = porNomeReal[nomeReal];
        if (!achado) faltando.push(nomeReal);
        return achado || null;
      });

      if (faltando.length) {
        callback(new Error(
          "NexusEsferasModelo: nao encontrei no glb os nos esperados: " + faltando.join(", ") +
          " -- nos disponiveis: " + Object.keys(porNomeReal).join(", ")
        ));
        return;
      }

      cacheGrupos = grupos;
      callback(null, grupos);
    }, function (erroParse) {
      callback(erroParse);
    });
  }

  global.NexusEsferasModelo = { NOMES: NOMES, carregar: carregar };
})(typeof window !== "undefined" ? window : this);
